<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});import {selectCampaign,selectCampaignMatches} from '~/demo/selectors.mjs';const route=useRoute(),demo=useDemoStore(),session=useSessionStore();const campaign=computed(()=>selectCampaign(demo.data,session.session||{},String(route.params.id)));const matches=computed(()=>selectCampaignMatches(demo.data,session.session||{},String(route.params.id)));const busy=ref(false),mode=ref(''),error=ref('');const results=computed(()=>campaign.value?.fitResults||[]);const shortlist=(id:string)=>demo.data.shortlists.some((x:any)=>x.campaignId===campaign.value?.id&&x.creatorId===id);async function analyze(){busy.value=true;error.value='';try{const body={campaignId:campaign.value.id,campaign:{name:campaign.value.name,brandName:campaign.value.brandName,product:campaign.value.product,objective:campaign.value.objective,audience:campaign.value.audience,languages:campaign.value.languages,formats:campaign.value.formats},creators:matches.value.map((c:any)=>({id:c.id}))};const res:any=await $fetch('/api/ai/creator-fit',{method:'POST',body});mode.value=res.mode;demo.run({type:'campaign:save-fit',campaignId:campaign.value.id,results:res.results},session.session||{})}catch(e:any){error.value=e?.data?.statusMessage||'Could not analyze creator fit. Try again.'}finally{busy.value=false}}
function toggle(id:string){demo.run({type:shortlist(id)?'shortlist:remove':'shortlist:add',campaignId:campaign.value.id,creatorId:id},session.session||{})}</script>
<template><div v-if="campaign" class="page-content"><div class="page-title-row"><div><NuxtLink class="flow-link" to="/app/campaigns">← Campaigns</NuxtLink><span class="page-label">CAMPAIGN MATCHING</span><h1>{{ campaign.name }}</h1><p>{{ campaign.brandName }} · {{ campaign.product }}</p></div><button class="button button-primary" :disabled="busy" @click="analyze">{{busy?'Analyzing…':'✦ Analyze creator fit'}}</button></div><section class="brief-panel"><h2>Creator brief</h2><p>{{ campaign.objective }}</p><div class="brief-metadata"><span class="tag">{{ campaign.audience }}</span><span v-for="x in campaign.languages" :key="x" class="tag tag-muted">{{x}}</span><span v-for="x in campaign.formats" :key="x" class="tag tag-violet">{{x}}</span></div></section><p v-if="error" class="form-hint" role="alert">{{error}}</p><div class="matching-layout" style="margin-top:16px"><section class="panel"><div class="panel-head"><div><h2>Creator fit</h2><p>AI estimated from public channel and video evidence</p></div><span v-if="mode" class="tag" :class="mode==='gemini'?'tag-violet':'tag-amber'">{{mode==='gemini'?'Generated with Gemini':'Sample preview'}}</span></div><div v-for="c in [...matches].sort((a:any,b:any)=>(results.find((x:any)=>x.creatorId===b.id)?.fitScore||0)-(results.find((x:any)=>x.creatorId===a.id)?.fitScore||0))" :key="c.id"><div class="creator-match"><span class="creator-avatar" style="background:#e6e0f8">{{c.name.slice(0,1)}}</span><div class="match-copy"><strong>{{c.name}}</strong><span>{{c.niche}} · {{c.channel.subscriberCount.toLocaleString()}} subscribers</span></div><div class="match-evidence"><span class="evidence-bar"><span style="width:82%"/></span><span>{{c.videos.length}} public videos</span></div><span v-if="results.find((x:any)=>x.creatorId===c.id)" class="fit-score-ring">{{results.find((x:any)=>x.creatorId===c.id).fitScore}}</span><button v-else class="button button-outline button-small" :disabled="busy" @click="analyze">Analyze</button></div><div v-if="results.find((x:any)=>x.creatorId===c.id)" class="match-insight"><strong>{{results.find((x:any)=>x.creatorId===c.id).summary}}</strong><p>{{results.find((x:any)=>x.creatorId===c.id).recommendation}}</p><div>{{results.find((x:any)=>x.creatorId===c.id).reasons.join(' · ')}}</div><button class="button button-small" :class="shortlist(c.id)?'button-soft':'button-outline'" style="margin-top:10px" @click="toggle(c.id)">{{shortlist(c.id)?'✓ Shortlisted':'＋ Add to shortlist'}}</button></div></div><div v-if="!results.length" class="empty-state">Analyze the creators to generate a fit score, reasons and recommendation.</div></section><aside class="panel side-summary"><div class="panel-head"><h2>Shortlist</h2><span class="tag tag-violet">{{demo.data.shortlists.filter((x:any)=>x.campaignId===campaign.id).length}} creators</span></div><div class="panel-body"><p class="secondary-text">Save creators to compare your strongest options for this brief.</p><div v-for="x in demo.data.shortlists.filter((x:any)=>x.campaignId===campaign.id)" :key="x.creatorId" class="summary-line"><span>{{demo.data.creators.find((c:any)=>c.id===x.creatorId)?.name}}</span><button class="button button-small button-outline" @click="toggle(x.creatorId)">Remove</button></div><div v-if="!demo.data.shortlists.some((x:any)=>x.campaignId===campaign.id)" class="empty-state">Your shortlist will appear here.</div><p class="form-hint">Public counters and creator profile text are sample evidence. Scores are estimates, not verified audience or brand safety data.</p></div></aside></div></div><div v-else class="page-content"><div class="empty-state">Campaign not found or outside this role's access.</div></div></template>
